package com.aistock.market.comparison;
import com.aistock.common.*;import com.aistock.market.marketlifecycle.*;import com.aistock.market.ingestion.CandidateRequestFilter;import com.fasterxml.jackson.databind.*;import java.util.*;import java.time.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class ComparisonLocalUseHttpTest {
 @Test void localAdmissionChangesOnlyAuthenticatedComparisonPost()throws Exception{var lifecycle=mock(MarketLifecycleService.class);var gate=new MarketEvidenceGate(lifecycle,true);var service=mock(ComparisonRefreshService.class);var json=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);var mvc=MockMvcBuilders.standaloneSetup(new ComparisonRefreshController(service,mock(ComparisonRefreshRepository.class))).setControllerAdvice(new ApiExceptionHandler()).addFilters(new CandidateRequestFilter("private",65536),new MarketEvidenceFilter(gate,json,true)).build();var request=new ComparisonUpdateRecords.Request(UUID.randomUUID(),"SH600030",UUID.randomUUID(),"a".repeat(64),LocalDate.parse("2025-10-13"),LocalDate.parse("2026-10-13"),ComparisonEvidenceValidator.DEFINITION,Instant.parse("2026-10-13T12:01:30Z"));String body=json.writeValueAsString(request);String uri="/internal/v1/market/comparison-refresh";mvc.perform(post(uri).contentType("application/json").content(body)).andExpect(status().isUnauthorized());verifyNoInteractions(service,lifecycle);when(service.refresh(any())).thenReturn(new ComparisonUpdateRecords.Result(request.operationId().toString(),"FAILED",null,"SOURCE_UNAVAILABLE"));mvc.perform(post(uri).header("X-Service-Token","private").contentType("application/json").content(body)).andExpect(status().isOk());verify(service,times(1)).refresh(any());mvc.perform(get("/internal/v1/market/analysis-evidence/SH600030").header("X-Service-Token","private")).andExpect(status().isBadRequest());var old=MockMvcBuilders.standaloneSetup(new ComparisonRefreshController(service,mock(ComparisonRefreshRepository.class))).setControllerAdvice(new ApiExceptionHandler()).addFilters(new CandidateRequestFilter("private",65536),new MarketEvidenceFilter(gate,json,false)).build();old.perform(post(uri).header("X-Service-Token","private").contentType("application/json").content(body)).andExpect(status().isBadRequest());verify(service,times(1)).refresh(any());verifyNoInteractions(lifecycle);}
}
